const daysAgo = (n) => {
  const d = new Date();
  d.setDate(d.getDate() - n);
  return d.toISOString();
};

const daysAhead = (n) => {
  const d = new Date();
  d.setDate(d.getDate() + n);
  return d.toISOString();
};

const notificationTemplates = [
  { type: 'due_soon', title: 'Book due soon', message: '"{book}" is due in 2 days. Please return it on time to avoid fines.' },
  { type: 'overdue', title: 'Overdue notice', message: '"{book}" is overdue. A fine of {fine} is now applied.' },
  { type: 'fine', title: 'Fine issued', message: 'A fine of {fine} was added to your account for "{book}".' },
  { type: 'reserved', title: 'Reservation ready', message: 'The book "{book}" you reserved is now available for pickup.' },
  { type: 'returned', title: 'Return confirmed', message: 'Thanks for returning "{book}". Your record has been updated.' },
  { type: 'announcement', title: 'Library announcement', message: 'The library will be closed on Sunday for maintenance.' },
  { type: 'system', title: 'Account update', message: 'Your account details were successfully updated.' },
  { type: 'new_arrival', title: 'New arrival', message: 'New book "{book}" has been added to the catalog. Check it out!' },
];

const books = [
  'The Pragmatic Programmer', 'Clean Code', '1984', 'Sapiens', 'Atomic Habits',
  'Deep Work', 'The Alchemist', 'Educated', 'Becoming', 'The Hobbit',
  'To Kill a Mockingbird', 'The Great Gatsby', 'Circe', 'The Night Circus',
  'The Lean Startup', 'Refactoring', 'Design Patterns', 'The Catcher in the Rye',
  'Harry Potter and the Sorcerer\'s Stone', 'The Lord of the Rings', 'Kite Runner',
  'Half of a Yellow Sun', 'Pride and Prejudice', 'Thinking, Fast and Slow',
  'The Immortal Life of Henrietta Lacks', 'Moneyball', 'The Signal and the Noise',
  'Black Swan', 'Antifragile', 'Dune', 'Foundation',
];

const fineAmounts = ['$1.00', '$2.50', '$5.00', '$7.50', '$10.00'];

const notifications = Array.from({ length: 35 }, (_, i) => {
  const tpl = notificationTemplates[i % notificationTemplates.length];
  const book = books[i % books.length];
  const fine = fineAmounts[i % fineAmounts.length];
  return {
    id: i + 1,
    type: tpl.type,
    title: tpl.title,
    message: tpl.message.replace('{book}', book).replace('{fine}', fine),
    read: i % 3 !== 0,
    created_at: daysAgo(i * 2 + (i % 5)),
  };
});

export default notifications;
